      횟수 = (typeof 횟수 === 'number' ? 횟수 : 0) + 1;
      document.getElementById("점수").textContent = 횟수;
      __beep(523.25, 0.1);
      if (횟수 == 10) {
        document.getElementById("점수").style.color = "#ef4444";
        __size("점수", "fontSize", 72);
        alert('10번 눌렀어요!');
      }
    });

    횟수 = 0;
  </script>
