      chars = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789!@#$%';
      document.getElementById("pw").textContent = '';
      for (var count = 0; count < 12; count++) {
        __add("pw", textRandomLetter(chars));
      }
    });
