<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>영어 학용품 퀴즈</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fce7f3; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>영어 학용품 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'지우개'의 영어 단어는?","a":"eraser","o":["pencil","bag","eraser","chair"]},{"q":"'의자'의 영어 단어는?","a":"chair","o":["pencil","desk","ruler","chair"]},{"q":"'공책'의 영어 단어는?","a":"notebook","o":["chair","book","notebook","scissors"]},{"q":"'가위'의 영어 단어는?","a":"scissors","o":["ruler","scissors","notebook","book"]},{"q":"'책상'의 영어 단어는?","a":"desk","o":["blackboard","eraser","desk","scissors"]},{"q":"'자'의 영어 단어는?","a":"ruler","o":["ruler","chair","eraser","blackboard"]},{"q":"'책'의 영어 단어는?","a":"book","o":["eraser","notebook","book","desk"]},{"q":"'칠판'의 영어 단어는?","a":"blackboard","o":["book","desk","scissors","blackboard"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
