<head>
  <meta charset="UTF-8">
  <title>OX 퀴즈</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="qText"></h2>
  <div id="btns" class="box row">
    <button id="oBtn">⭕ O</button>
    <button id="xBtn">❌ X</button>
  </div>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var pick, qs, right, i, ans;

    // 이 함수를 설명하세요...
    function answer(pick) {
      if (pick == ans[(i - 1)]) {
        right = (typeof right === 'number' ? right : 0) + 1;
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > 5) {
        document.getElementById("qText").textContent = ['5문제 중 ',right,'개 맞혔어요'].join('');
        __show("btns", "hide");
      } else {
        document.getElementById("qText").textContent = qs[(i - 1)];
      }
    }

    document.getElementById("oBtn").addEventListener('click', function () {
      answer('O');
    });
    document.getElementById("xBtn").addEventListener('click', function () {
