  <script>
    const questions = [{"q":"'수요일'의 영어 단어는?","a":"Wednesday","o":["Sunday","Wednesday","Thursday"]},{"q":"'화요일'의 영어 단어는?","a":"Tuesday","o":["Wednesday","Tuesday","Thursday"]},{"q":"'금요일'의 영어 단어는?","a":"Friday","o":["Sunday","Friday","Wednesday"]},{"q":"'토요일'의 영어 단어는?","a":"Saturday","o":["Saturday","Sunday","Friday"]},{"q":"'목요일'의 영어 단어는?","a":"Thursday","o":["Thursday","Wednesday","Saturday"]},{"q":"'월요일'의 영어 단어는?","a":"Monday","o":["Friday","Wednesday","Monday"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
