  <style>
    body { font-family: sans-serif; text-align: center; background: #e0f2fe; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; padding: 8px; margin: 4px; }
  </style>
</head>
<body>
  <h1>그림판</h1>
  <canvas id="board" width="400" height="300" style="background: white; border: 1px solid #999"></canvas>
  <div><button id="clear">지우기</button></div>
  <script>
    const canvas = document.getElementById('board');
    const ctx = canvas.getContext('2d');
    let drawing = false;
    canvas.addEventListener('mousedown', function () { drawing = true; ctx.beginPath(); });
    canvas.addEventListener('mouseup', function () { drawing = false; });
    canvas.addEventListener('mousemove', function (e) {
      if (!drawing) return;
      const rect = canvas.getBoundingClientRect();
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
      ctx.stroke();
    });
    document.getElementById('clear').addEventListener('click', function () {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    });
  </script>
</body>
</html>
