      __circle("그림판1", x, y, 14, "#38bdf8");
      if (__dist(x, y, sx, sy) < 25) {
        score = (typeof score === 'number' ? score : 0) + 1;
        sx = mathRandomInt(20, 300);
        sy = mathRandomInt(20, 200);
        __beep(261.63, 0.08);
        document.getElementById("점수판").textContent = '점수: ' + String(score);
      }
    }, 30));
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        y = (typeof y === 'number' ? y : 0) + 10;
      }
    });
    document.getElementById("그림판1").style.touchAction = 'none';
    document.getElementById("그림판1").addEventListener('pointermove', function (e) {
      if (!e.buttons) return;
      __pos(e, this);
      x = __mx;
      y = __my;
    });
    __timers.push(setInterval(function () {
      left = (typeof left === 'number' ? left : 0) + -1;
      document.getElementById("남은시간").textContent = '남은 시간: ' + String(left);
      if (left <= 0) {
        __timers.forEach(clearInterval);
        if (score > __load('최고점', 0)) {
          __save('최고점', score);
          document.getElementById("최고기록").textContent = '새 기록! ' + String(score);
        }
        alert('끝! 점수는 ' + String(score));
      }
    }, 1000));

    x = 160;
