  <script>
    const questions = [{"q":"4 × 2 = ?","a":"8","o":["8","11","5","7"]},{"q":"53 - 21 = ?","a":"32","o":["34","32","37","22"]},{"q":"41 + 58 = ?","a":"99","o":["89","99","100","109"]},{"q":"4 × 7 = ?","a":"28","o":["29","27","28","30"]},{"q":"3 × 9 = ?","a":"27","o":["24","27","32","29"]},{"q":"17 + 60 = ?","a":"77","o":["77","74","79","87"]},{"q":"38 - 11 = ?","a":"27","o":["27","26","24","32"]},{"q":"28 - 17 = ?","a":"11","o":["12","11","13","8"]},{"q":"40 + 39 = ?","a":"79","o":["80","79","81","89"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
