  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    __timers.push(setInterval(function () {
      document.getElementById("now").textContent = [new Date().getHours(),':',new Date().getMinutes(),':',new Date().getSeconds()].join('');
      document.getElementById("day").textContent = ['일요일', '월요일', '화요일', '수요일', '목요일', '금요일', '토요일'][((new Date().getDay() + 1) - 1)];
    }, 1000));
    document.getElementById("tog").addEventListener('click', function () {
      __show("now", "toggle");
    });

    document.getElementById("now").style.color = "#3b82f6";
    document.getElementById("day").style.color = "#3b82f6";
  </script>
</body>
