  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'지우개'의 영어 단어는?","a":"eraser","o":["pencil","eraser","bag","ruler"]},{"q":"'칠판'의 영어 단어는?","a":"blackboard","o":["blackboard","notebook","eraser","bag"]},{"q":"'연필'의 영어 단어는?","a":"pencil","o":["bag","pencil","chair","desk"]},{"q":"'가방'의 영어 단어는?","a":"bag","o":["eraser","bag","ruler","desk"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
