  <button id="next">다음</button>
  <script>
    const cards = [["토요일","Saturday"],["월요일","Monday"],["화요일","Tuesday"],["일요일","Sunday"],["목요일","Thursday"],["수요일","Wednesday"],["금요일","Friday"]];
