    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var bal;

    document.getElementById("inBtn").addEventListener('click', function () {
      bal = (typeof bal === 'number' ? bal : 0) + (parseFloat(document.getElementById("moneyBox").value) || 0);
      __add("log", '+' + String((parseFloat(document.getElementById("moneyBox").value) || 0)));
      document.getElementById("balText").textContent = ['잔액 ',bal,'원'].join('');
    });
    document.getElementById("outBtn").addEventListener('click', function () {
      if (bal - (parseFloat(document.getElementById("moneyBox").value) || 0) < 0) {
        alert('잔액 부족!');
      } else {
        bal = (typeof bal === 'number' ? bal : 0) + -(parseFloat(document.getElementById("moneyBox").value) || 0);
        __add("log", '-' + String((parseFloat(document.getElementById("moneyBox").value) || 0)));
        document.getElementById("balText").textContent = ['잔액 ',bal,'원'].join('');
      }
    });

    bal = 0;
  </script>
