  </style>
</head>
<body>
  <h1 id="time">10</h1>
  <input id="sec" type="number" placeholder="몇 초? (비우면 그대로)">
  <div id="r" class="box row">
    <button id="go">시작</button>
    <button id="pause">일시정지</button>
  </div>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var t, on;

    document.getElementById("go").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("sec").value) || 0) > 0) {
        t = (parseFloat(document.getElementById("sec").value) || 0);
        document.getElementById("time").textContent = t;
        document.getElementById("time").style.color = "#111111";
        document.getElementById("sec").value = '';
      }
      if (t > 0) {
        on = true;
      }
    });
    document.getElementById("pause").addEventListener('click', function () {
      on = false;
    });
    __timers.push(setInterval(function () {
      if (on) {
        t = (typeof t === 'number' ? t : 0) + -1;
        document.getElementById("time").textContent = t;
        if (t <= 5) {
          document.getElementById("time").style.color = "#ef4444";
        }
        if (t == 0) {
          on = false;
          document.getElementById("time").textContent = '끝!';
          __beep(440.00, 0.6);
        }
      }
    }, 1000));

    t = 10;
    on = false;
  </script>
</body>
