  <h2 id="title">Frog Pad</h2>
  <p id="hint">Tap the buttons</p>
  <div id="pad" class="box row">
    <button id="bL">Left</button>
    <button id="bU">Up</button>
    <button id="bD">Down</button>
    <button id="bR">Right</button>
  </div>
  <h1 id="hero">🐸</h1>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __stay(name) {
      var el = $(name), s = el.style, d = document.documentElement;
      if (s.position !== 'absolute') return;
      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }

    document.getElementById("bL").addEventListener('click', function () {
      __nudge("hero", -25, 0);
      __stay("hero");
    });
    document.getElementById("bU").addEventListener('click', function () {
      __nudge("hero", 0, -25);
      __stay("hero");
    });
    document.getElementById("bD").addEventListener('click', function () {
      __nudge("hero", 0, 25);
      __stay("hero");
    });
    document.getElementById("bR").addEventListener('click', function () {
      __nudge("hero", 25, 0);
      __stay("hero");
    });

    __move("hero", 140, 200);
  </script>
</body>
</html>
