  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'사자'의 영어 단어는?","a":"lion","o":["monkey","tiger","bear","lion"]},{"q":"'원숭이'의 영어 단어는?","a":"monkey","o":["monkey","horse","lion","cat"]},{"q":"'돼지'의 영어 단어는?","a":"pig","o":["tiger","giraffe","pig","bear"]},{"q":"'오리'의 영어 단어는?","a":"duck","o":["rabbit","duck","dog","tiger"]},{"q":"'곰'의 영어 단어는?","a":"bear","o":["duck","rabbit","tiger","bear"]},{"q":"'코끼리'의 영어 단어는?","a":"elephant","o":["cat","giraffe","monkey","elephant"]},{"q":"'고양이'의 영어 단어는?","a":"cat","o":["dog","horse","tiger","cat"]},{"q":"'말'의 영어 단어는?","a":"horse","o":["rabbit","tiger","horse","dog"]},{"q":"'호랑이'의 영어 단어는?","a":"tiger","o":["tiger","cat","lion","elephant"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
