    const questions = [{"q":"태양에서 5번째로 가까운 행성은?","a":"목성","o":["지구","화성","목성","수성"]},{"q":"태양에서 1번째로 가까운 행성은?","a":"수성","o":["목성","수성","토성","화성"]},{"q":"태양에서 8번째로 가까운 행성은?","a":"해왕성","o":["토성","해왕성","목성","화성"]},{"q":"태양에서 7번째로 가까운 행성은?","a":"천왕성","o":["지구","화성","토성","천왕성"]},{"q":"태양에서 4번째로 가까운 행성은?","a":"화성","o":["지구","목성","화성","토성"]}];
