<body>
  <h1>영어 가족 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'엄마'의 영어 단어는?","a":"mom","o":["dad","mom","older sister"]},{"q":"'누나'의 영어 단어는?","a":"older sister","o":["dad","grandmother","older sister"]},{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["older brother","grandfather","grandmother"]},{"q":"'동생'의 영어 단어는?","a":"younger sibling","o":["grandmother","grandfather","younger sibling"]},{"q":"'아빠'의 영어 단어는?","a":"dad","o":["mom","younger sibling","dad"]},{"q":"'할머니'의 영어 단어는?","a":"grandmother","o":["older brother","grandfather","grandmother"]},{"q":"'형'의 영어 단어는?","a":"older brother","o":["older brother","mom","younger sibling"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
