  <script>
    const questions = [{"q":"'아빠'의 영어 단어는?","a":"dad","o":["grandmother","mom","dad"]},{"q":"'동생'의 영어 단어는?","a":"younger sibling","o":["mom","older brother","younger sibling"]},{"q":"'할머니'의 영어 단어는?","a":"grandmother","o":["dad","grandmother","older brother"]},{"q":"'누나'의 영어 단어는?","a":"older sister","o":["grandmother","older sister","grandfather"]},{"q":"'엄마'의 영어 단어는?","a":"mom","o":["older brother","grandfather","mom"]},{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["grandfather","younger sibling","grandmother"]},{"q":"'형'의 영어 단어는?","a":"older brother","o":["grandfather","younger sibling","older brother"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
