    const questions = [{"q":"개의 울음소리는?","a":"멍멍","o":["멍멍","음메","꿀꿀","까악까악"]},{"q":"참새의 울음소리는?","a":"짹짹","o":["멍멍","메에","짹짹","개굴개굴"]},{"q":"개구리의 울음소리는?","a":"개굴개굴","o":["멍멍","꿀꿀","개굴개굴","음메"]},{"q":"소의 울음소리는?","a":"음메","o":["음메","까악까악","꿀꿀","짹짹"]},{"q":"까마귀의 울음소리는?","a":"까악까악","o":["짹짹","까악까악","부엉부엉","꼬꼬댁"]}];
