    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    var __cx = 0, __cy = 0;

    document.getElementById("sq").style.touchAction = 'none';
    document.getElementById("sq").addEventListener('pointermove', function (e) {
      if (!e.buttons) return;
      __pos(e, this);
      __move("sq", __cx, __cy);
