    canvas { background: #ffffff; border: 3px solid #94a3b8; border-radius: 8px; }
  </style>
</head>
<body>
  <h1>튕기는 공</h1>
  <canvas id="canvas" width="480" height="320"></canvas>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const balls = [];

    function addBall() {
      balls.push({
        x: Math.random() * (canvas.width - 46) + 23,
        y: Math.random() * (canvas.height - 46) + 23,
        dx: (Math.random() < 0.5 ? -1 : 1) * 4,
        dy: (Math.random() < 0.5 ? -1 : 1) * 4
      });
    }

    for (let i = 0; i < 3; i++) {
      addBall();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      balls.forEach(function (b) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < 23 || b.x > canvas.width - 23) b.dx = -b.dx;
        if (b.y < 23 || b.y > canvas.height - 23) b.dy = -b.dy;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 23, 0, Math.PI * 2);
        ctx.fillStyle = '#3b82f6';
        ctx.fill();
      });
      requestAnimationFrame(draw);
    }

    draw();
  </script>
</body>
</html>
