  <p id="feedback"></p>
  <script>
    const questions = [{"q":"고양이의 울음소리는?","a":"야옹","o":["멍멍","부엉부엉","야옹"]},{"q":"참새의 울음소리는?","a":"짹짹","o":["짹짹","개굴개굴","멍멍"]},{"q":"소의 울음소리는?","a":"음메","o":["음메","꼬꼬댁","까악까악"]},{"q":"양의 울음소리는?","a":"메에","o":["부엉부엉","어흥","메에"]}];
