    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var h;

    // 이 함수를 설명하세요...
    function show() {
      document.getElementById("hun").textContent = 'Hunger: ' + String(h);
      if (h >= 7) {
        document.getElementById("pet").textContent = '🥺';
      } else {
        document.getElementById("pet").textContent = '🐶';
      }
    }

    __timers.push(setInterval(function () {
      h = (typeof h === 'number' ? h : 0) + 1;
      show();
      if (h >= 10) {
        __timers.forEach(clearInterval);
        document.getElementById("pet").textContent = '😢';
        document.getElementById("hun").textContent = 'Your pet is sad... game over';
        __show("feed", "hide");
      }
    }, 2000));
    document.getElementById("feed").addEventListener('click', function () {
      h = h - 3;
      if (h < 0) {
        h = 0;
      }
      show();
    });

    h = 0;
