<body>
  <h1>튕기는 공</h1>
  <canvas id="canvas" width="480" height="320"></canvas>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const balls = [];

    function addBall() {
      balls.push({
        x: Math.random() * (canvas.width - 36) + 18,
        y: Math.random() * (canvas.height - 36) + 18,
        dx: (Math.random() < 0.5 ? -1 : 1) * 4,
        dy: (Math.random() < 0.5 ? -1 : 1) * 4
      });
    }

    for (let i = 0; i < 5; i++) {
      addBall();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      balls.forEach(function (b) {
        b.x += b.dx;
        b.y += b.dy;
        if (b.x < 18 || b.x > canvas.width - 18) b.dx = -b.dx;
        if (b.y < 18 || b.y > canvas.height - 18) b.dy = -b.dy;
        ctx.beginPath();
        ctx.arc(b.x, b.y, 18, 0, Math.PI * 2);
        ctx.fillStyle = '#f97316';
        ctx.fill();
      });
      requestAnimationFrame(draw);
    }

    draw();
  </script>
</body>
</html>
