    const questions = [{"q":"'초록'의 영어 단어는?","a":"green","o":["white","green","purple"]},{"q":"'보라'의 영어 단어는?","a":"purple","o":["white","purple","blue"]},{"q":"'하양'의 영어 단어는?","a":"white","o":["black","red","white"]},{"q":"'파랑'의 영어 단어는?","a":"blue","o":["blue","orange","pink"]}];
