      document.getElementById("res").textContent = '';
      if ((parseFloat(document.getElementById("cnt").value) || 0) < 1) {
        alert('1명 이상 써 주세요');
      } else {
        pool = [];
        var i_end = (parseFloat(document.getElementById("cnt").value) || 0);
