      if (!drawing) return;
      const rect = canvas.getBoundingClientRect();
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
      ctx.stroke();
    });
    document.getElementById('clear').addEventListener('click', function () {
      beep();
      ctx.clearRect(0, 0, canvas.width, canvas.height);
