    <button id="b2">✊ 바위</button>
    <button id="b3">🖐️ 보</button>
  </div>
  <h2 id="result"></h2>
  <p id="board">나 : 컴퓨터 = 0 : 0</p>
  <h2 id="final"></h2>
  <button id="again">다시</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var me, w, com, l, played, d;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function play(me) {
      if (played < 7) {
        com = mathRandomInt(1, 3);
        played = (typeof played === 'number' ? played : 0) + 1;
        d = ((me - com) + 3) % 3;
        if (d == 1) {
          w = (typeof w === 'number' ? w : 0) + 1;
          document.getElementById("result").textContent = '이겼다!';
          __beep(523.25, 0.15);
        } else if (d == 2) {
          l = (typeof l === 'number' ? l : 0) + 1;
          document.getElementById("result").textContent = '졌다...';
          __beep(261.63, 0.15);
        } else {
          document.getElementById("result").textContent = '비김';
        }
        document.getElementById("board").textContent = ['나 : 컴퓨터 = ',w,' : ',l,' (',played,'/7)'].join('');
        if (played == 7) {
          document.getElementById("final").textContent = w > l ? '🏆 최종 승리!' : (w < l ? '😭 최종 패배' : '무승부!');
          __show("again", "show");
        }
      }
    }

    document.getElementById("b1").addEventListener('click', function () {
      play(1);
    });
    document.getElementById("b2").addEventListener('click', function () {
      play(2);
    });
    document.getElementById("b3").addEventListener('click', function () {
      play(3);
    });
    document.getElementById("again").addEventListener('click', function () {
      w = 0;
      l = 0;
      played = 0;
      document.getElementById("final").textContent = '';
      document.getElementById("result").textContent = '';
      __show("again", "hide");
    });

    w = 0;
    l = 0;
    played = 0;
    document.getElementById("final").textContent = '';
    document.getElementById("result").textContent = '';
    __show("again", "hide");
  </script>
</body>
</html>
