    document.getElementById("box").addEventListener('input', function () {
      s = document.getElementById("box").value;
      ns = 0;
      var k_end = s.length;
      var k_inc = 1;
      if (1 > k_end) {
        k_inc = -k_inc;
      }
      for (k = 1; k_inc >= 0 ? k <= k_end : k >= k_end; k += k_inc) {
        if (s.charAt((k - 1)) != ' ') {
          ns = (typeof ns === 'number' ? ns : 0) + 1;
        }
      }
      document.getElementById("count").textContent = ['글자 수: ',s.length,' / 100'].join('');
      document.getElementById("nospace").textContent = '공백 빼고: ' + String(ns);
      if (s.length > 100) {
        document.getElementById("warn").textContent = '⚠️ 100자를 넘었어요!';
        document.getElementById("count").style.color = "#ef4444";
      } else {
        document.getElementById("warn").textContent = '';
        document.getElementById("count").style.color = "#111111";
