    var last, w;

    document.getElementById("goBtn").addEventListener('click', function () {
      w = document.getElementById("wordBox").value.trim();
      if (!!w.length && w.charAt(0) == last.slice(-1)) {
        __add("chain", w);
        last = w;
        document.getElementById("lastWord").textContent = w;
        document.getElementById("msg").textContent = '';
        document.getElementById("wordBox").value = '';
      } else {
        document.getElementById("msg").textContent = '끝말이 안 이어져요';
      }
    });

    last = '기차';
  </script>
