    const questions = [{"q":"'할머니'의 영어 단어는?","a":"grandmother","o":["grandmother","grandfather","older sister"]},{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["grandfather","dad","grandmother"]},{"q":"'아빠'의 영어 단어는?","a":"dad","o":["dad","younger sibling","older sister"]},{"q":"'엄마'의 영어 단어는?","a":"mom","o":["older brother","younger sibling","mom"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
