  <script>
    const questions = [{"q":"'다리'의 영어 단어는?","a":"leg","o":["hand","eye","leg","head"]},{"q":"'손'의 영어 단어는?","a":"hand","o":["leg","mouth","head","hand"]},{"q":"'코'의 영어 단어는?","a":"nose","o":["head","nose","eye","hand"]},{"q":"'귀'의 영어 단어는?","a":"ear","o":["eye","ear","leg","hand"]},{"q":"'팔'의 영어 단어는?","a":"arm","o":["arm","hand","eye","mouth"]},{"q":"'눈'의 영어 단어는?","a":"eye","o":["leg","arm","head","eye"]},{"q":"'머리'의 영어 단어는?","a":"head","o":["hand","head","eye","nose"]},{"q":"'발'의 영어 단어는?","a":"foot","o":["foot","hand","ear","nose"]},{"q":"'입'의 영어 단어는?","a":"mouth","o":["head","leg","mouth","foot"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
