  <h2 id="title">소풍 장소 투표</h2>
  <div id="choices" class="box row">
    <button id="o0">산</button>
    <button id="o1">바다</button>
    <button id="o2">놀이공원</button>
  </div>
  <p id="r0">산: 0</p>
  <p id="r1">바다: 0</p>
  <p id="r2">놀이공원: 0</p>
  <p id="total">총 0표</p>
  <h3 id="lead"></h3>
  <script>
    var name2, cnt, k, votes, sum, top2, x, names;

    // 이 함수를 설명하세요...
    function lineOf(name2, cnt) {
      return [name2,': ',cnt,'표'].join('');
    }

    // 이 함수를 설명하세요...
    function cast(k) {
      votes[(k - 1)] = votes[(k - 1)] + 1;
      sum = 0;
      for (var x_index in votes) {
        x = votes[x_index];
        sum = (typeof sum === 'number' ? sum : 0) + x;
      }
      document.getElementById("r0").textContent = lineOf('산', votes[0]);
      document.getElementById("r1").textContent = lineOf('바다', votes[1]);
      document.getElementById("r2").textContent = lineOf('놀이공원', votes[2]);
      document.getElementById("total").textContent = ['총 ',sum,'표'].join('');
      if (votes[(k - 1)] > votes[(top2 - 1)]) {
        top2 = k;
      }
      document.getElementById("lead").textContent = '1등: ' + String(names[(top2 - 1)]);
    }

    function listsRepeat(value, n) {
      var array = [];
      for (var i = 0; i < n; i++) {
        array[i] = value;
      }
      return array;
    }

    document.getElementById("o0").addEventListener('click', function () {
      cast(1);
    });
    document.getElementById("o1").addEventListener('click', function () {
      cast(2);
    });
    document.getElementById("o2").addEventListener('click', function () {
      cast(3);
    });

    votes = listsRepeat(0, 3);
    top2 = 1;
    names = ['산', '바다', '놀이공원'];
  </script>
</body>
</html>
