  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'빨강'의 영어 단어는?","a":"red","o":["purple","red","brown"]},{"q":"'보라'의 영어 단어는?","a":"purple","o":["pink","purple","black"]},{"q":"'검정'의 영어 단어는?","a":"black","o":["pink","black","purple"]},{"q":"'하양'의 영어 단어는?","a":"white","o":["white","orange","pink"]},{"q":"'노랑'의 영어 단어는?","a":"yellow","o":["gray","green","yellow"]},{"q":"'갈색'의 영어 단어는?","a":"brown","o":["black","brown","orange"]},{"q":"'초록'의 영어 단어는?","a":"green","o":["red","orange","green"]},{"q":"'회색'의 영어 단어는?","a":"gray","o":["gray","purple","black"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
