    var answer, tries, guess;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    function guess2() {
      // If it is empty or not 1–100, ask again
      if (!document.getElementById("numberBox").value.length || !(((parseFloat(document.getElementById("numberBox").value) || 0)) >= (1) && ((parseFloat(document.getElementById("numberBox").value) || 0)) <= (100))) {
        document.getElementById("result").textContent = '✋ Please type a number from 1 to 100';
        document.getElementById("result").style.color = "#ef4444";
      } else {
        tries = (typeof tries === 'number' ? tries : 0) + 1;
        guess = (parseFloat(document.getElementById("numberBox").value) || 0);
        document.getElementById("triesText").textContent = ['Tries: ',tries,''].join('');
        // Compare with the answer and give a hint
        if (guess == answer) {
          document.getElementById("result").textContent = ['🎉 Correct! ',tries,' tries to get it'].join('');
          document.getElementById("result").style.color = "#ef4444";
          __sfx("win");
          __show("Check", "hide");
          __show("newGame", "show");
        } else if (guess < answer) {
          document.getElementById("result").textContent = String(guess) + ' — it is bigger ⬆';
          document.getElementById("result").style.color = "#facc15";
          __beep(392.00, 0.1);
        } else {
          document.getElementById("result").textContent = String(guess) + ' — it is smaller ⬇';
          document.getElementById("result").style.color = "#38bdf8";
          __beep(293.66, 0.1);
        }
        document.getElementById("numberBox").value = '';
      }
    }

    document.getElementById("newGame").addEventListener('click', function () {
      // The computer secretly picks a number from 1 to 100
      answer = mathRandomInt(1, 100);
