  </style>
</head>
<body>
  <h1 id="title">Use the arrow keys</h1>
  <canvas id="area" width="300" height="200"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }

    var x, y;

    // 이 함수를 설명하세요...
    function draw() {
      x = Math.min(Math.max(x, 0), 270);
      y = Math.min(Math.max(y, 0), 170);
      __clear("area");
      __rect("area", x, y, 30, 30, "#22c55e");
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + -10;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + 10;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        y = (typeof y === 'number' ? y : 0) + -10;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        y = (typeof y === 'number' ? y : 0) + 10;
        draw();
      }
    });

    x = 135;
    y = 85;
    draw();
  </script>
</body>
</html>
