  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'입'의 영어 단어는?","a":"mouth","o":["head","hand","mouth","ear"]},{"q":"'코'의 영어 단어는?","a":"nose","o":["nose","head","arm","ear"]},{"q":"'발'의 영어 단어는?","a":"foot","o":["ear","leg","arm","foot"]},{"q":"'다리'의 영어 단어는?","a":"leg","o":["mouth","leg","eye","head"]},{"q":"'손'의 영어 단어는?","a":"hand","o":["hand","mouth","ear","head"]},{"q":"'팔'의 영어 단어는?","a":"arm","o":["head","arm","nose","mouth"]},{"q":"'머리'의 영어 단어는?","a":"head","o":["foot","arm","ear","head"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
