        if (timeLeft <= 0) endGame();
      }, 1000);
    }

    function endGame() {
      running = false;
      clearInterval(timer);
      timeLeft = 0;
      document.getElementById('time').textContent = 0;
      input.disabled = true;
      wordEl.textContent = '끝!';
      msg.textContent = '⏰ 게임 끝! 1분 동안 ' + score + '개 맞혔어요';
    }

    // 단어를 똑같이 치면 바로 다음 단어로
    input.addEventListener('input', function () {
      if (!running) return;
      if (input.value.trim() === current) {
        score += 1;
        document.getElementById('score').textContent = score;
        input.value = '';
        nextWord();
      }
    });

    startBtn.addEventListener('click', startGame);
  </script>
</body>
</html>
