  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'금요일'의 영어 단어는?","a":"Friday","o":["Friday","Tuesday","Saturday","Monday"]},{"q":"'토요일'의 영어 단어는?","a":"Saturday","o":["Monday","Saturday","Sunday","Wednesday"]},{"q":"'화요일'의 영어 단어는?","a":"Tuesday","o":["Monday","Wednesday","Sunday","Tuesday"]},{"q":"'월요일'의 영어 단어는?","a":"Monday","o":["Wednesday","Friday","Thursday","Monday"]},{"q":"'목요일'의 영어 단어는?","a":"Thursday","o":["Thursday","Sunday","Monday","Tuesday"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
