  <script>
    var name2, cnt, k, votes, sum, top2, x, names;

    // 이 함수를 설명하세요...
    function lineOf(name2, cnt) {
      return [name2,': ',cnt,'표',' (',Math.round((cnt * 100) / sum),'%)'].join('');
    }

    // 이 함수를 설명하세요...
    function cast(k) {
      votes[(k - 1)] = votes[(k - 1)] + 1;
      sum = 0;
      for (var x_index in votes) {
        x = votes[x_index];
        sum = (typeof sum === 'number' ? sum : 0) + x;
      }
      document.getElementById("r0").textContent = lineOf('피자', votes[0]);
      document.getElementById("r1").textContent = lineOf('치킨', votes[1]);
