      document.getElementById("r3").textContent = lineOf('떡볶이', votes[3]);
      document.getElementById("total").textContent = ['총 ',sum,'표'].join('');
    }

    function listsRepeat(value, n) {
      var array = [];
      for (var i = 0; i < n; i++) {
        array[i] = value;
      }
      return array;
    }

    document.getElementById("resetBtn").addEventListener('click', function () {
      votes = listsRepeat(0, 4);
      top2 = 1;
      document.getElementById("r0").textContent = '피자: 0';
      document.getElementById("r1").textContent = '치킨: 0';
