    const questions = [{"q":"'목요일'의 영어 단어는?","a":"Thursday","o":["Thursday","Wednesday","Monday"]},{"q":"'월요일'의 영어 단어는?","a":"Monday","o":["Monday","Saturday","Wednesday"]},{"q":"'수요일'의 영어 단어는?","a":"Wednesday","o":["Saturday","Wednesday","Thursday"]},{"q":"'토요일'의 영어 단어는?","a":"Saturday","o":["Sunday","Tuesday","Saturday"]},{"q":"'일요일'의 영어 단어는?","a":"Sunday","o":["Thursday","Wednesday","Sunday"]}];
