  <div id="keys" class="box row">
    <button id="k1">Do</button>
    <button id="k2">Re</button>
    <button id="k3">Mi</button>
    <button id="k4">Fa</button>
  </div>
  <p id="played"></p>
  <button id="clear">Clear</button>
