    document.getElementById("k3").addEventListener('click', function () {
      __beep(329.63, 0.3);
      __add("played", 'Mi ');
    });
    document.getElementById("k4").addEventListener('click', function () {
      __beep(349.23, 0.3);
      __add("played", 'Fa ');
    });
    document.getElementById("clear").addEventListener('click', function () {
      document.getElementById("played").textContent = '';
    });

    document.getElementById("k1").style.background = "#ef4444";
    document.getElementById("k2").style.background = "#f97316";
    document.getElementById("k3").style.background = "#facc15";
    document.getElementById("k4").style.background = "#22c55e";
