    <button id="d2">수 ⬜</button>
    <button id="d3">목 ⬜</button>
    <button id="d4">금 ⬜</button>
    <button id="d5">토 ⬜</button>
    <button id="d6">일 ⬜</button>
  </div>
  <h3 id="count">이번 주 성공: 0일</h3>
  <h3 id="msg"></h3>
  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var k, done, c, x;

    // 이 함수를 설명하세요...
    function tick(k) {
      done[(k - 1)] = !done[(k - 1)];
      c = 0;
      for (var x_index in done) {
        x = done[x_index];
        if (x) {
          c = (typeof c === 'number' ? c : 0) + 1;
        }
      }
      document.getElementById("count").textContent = ['이번 주 성공: ',c,'일'].join('');
      if (c == 7) {
        document.getElementById("msg").textContent = '🔥 이번 주 전부 성공!';
        __beep(523.25, 0.3);
      } else {
        document.getElementById("msg").textContent = '';
      }
    }

    function listsRepeat(value, n) {
      var array = [];
      for (var i = 0; i < n; i++) {
        array[i] = value;
      }
      return array;
    }

    document.getElementById("d0").addEventListener('click', function () {
      tick(1);
      document.getElementById("d0").textContent = done[0] ? '월 ✅' : '월 ⬜';
    });
    document.getElementById("d1").addEventListener('click', function () {
      tick(2);
      document.getElementById("d1").textContent = done[1] ? '화 ✅' : '화 ⬜';
    });
    document.getElementById("d2").addEventListener('click', function () {
      tick(3);
      document.getElementById("d2").textContent = done[2] ? '수 ✅' : '수 ⬜';
    });
    document.getElementById("d3").addEventListener('click', function () {
      tick(4);
      document.getElementById("d3").textContent = done[3] ? '목 ✅' : '목 ⬜';
    });
    document.getElementById("d4").addEventListener('click', function () {
      tick(5);
      document.getElementById("d4").textContent = done[4] ? '금 ✅' : '금 ⬜';
    });
    document.getElementById("d5").addEventListener('click', function () {
      tick(6);
      document.getElementById("d5").textContent = done[5] ? '토 ✅' : '토 ⬜';
    });
    document.getElementById("d6").addEventListener('click', function () {
      tick(7);
      document.getElementById("d6").textContent = done[6] ? '일 ✅' : '일 ⬜';
    });

    done = listsRepeat(false, 7);
  </script>
</body>
</html>
