  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'포도'의 영어 단어는?","a":"grape","o":["strawberry","peach","grape"]},{"q":"'복숭아'의 영어 단어는?","a":"peach","o":["peach","apple","grape"]},{"q":"'귤'의 영어 단어는?","a":"tangerine","o":["cherry","tangerine","apple"]},{"q":"'바나나'의 영어 단어는?","a":"banana","o":["watermelon","banana","lemon"]},{"q":"'배'의 영어 단어는?","a":"pear","o":["grape","banana","pear"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
