  </style>
</head>
<body>
  <h1>영어 몸 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'눈'의 영어 단어는?","a":"eye","o":["head","eye","ear","hand"]},{"q":"'머리'의 영어 단어는?","a":"head","o":["head","hand","foot","eye"]},{"q":"'발'의 영어 단어는?","a":"foot","o":["eye","leg","mouth","foot"]},{"q":"'코'의 영어 단어는?","a":"nose","o":["nose","foot","head","ear"]},{"q":"'귀'의 영어 단어는?","a":"ear","o":["ear","arm","nose","hand"]},{"q":"'손'의 영어 단어는?","a":"hand","o":["foot","ear","hand","nose"]},{"q":"'입'의 영어 단어는?","a":"mouth","o":["mouth","hand","eye","leg"]},{"q":"'다리'의 영어 단어는?","a":"leg","o":["eye","nose","head","leg"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
