  <button id="paperBtn">✋</button>
  <h1 id="rpShow">❔</h1>
  <h1 id="rpRes"></h1>
  <script>
    var mine, cpu;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function judge() {
      cpu = mathRandomInt(1, 3);
      document.getElementById("rpShow").textContent = '✊✌✋'.charAt((cpu - 1));
      if (mine == cpu) {
        document.getElementById("rpRes").textContent = 'あいこ 🤝';
      } else if (((mine - cpu) + 3) % 3 == 2) {
        document.getElementById("rpRes").textContent = '勝ち！🎉';
      } else {
        document.getElementById("rpRes").textContent = '負け 😢';
      }
    }

    document.getElementById("rockBtn").addEventListener('click', function () {
      mine = 1;
      judge();
    });
    document.getElementById("scisBtn").addEventListener('click', function () {
      mine = 2;
      judge();
    });
    document.getElementById("paperBtn").addEventListener('click', function () {
      mine = 3;
      judge();
    });
  </script>
