  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'지우개'의 영어 단어는?","a":"eraser","o":["bag","eraser","pencil"]},{"q":"'가위'의 영어 단어는?","a":"scissors","o":["ruler","scissors","desk"]},{"q":"'연필'의 영어 단어는?","a":"pencil","o":["book","pencil","ruler"]},{"q":"'공책'의 영어 단어는?","a":"notebook","o":["book","notebook","eraser"]},{"q":"'자'의 영어 단어는?","a":"ruler","o":["blackboard","ruler","chair"]},{"q":"'의자'의 영어 단어는?","a":"chair","o":["chair","eraser","notebook"]},{"q":"'책'의 영어 단어는?","a":"book","o":["book","scissors","pencil"]},{"q":"'책상'의 영어 단어는?","a":"desk","o":["desk","eraser","bag"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
