    document.getElementById("cv").style.touchAction = 'none';
    document.getElementById("cv").addEventListener('pointermove', function (e) {
      if (!e.buttons) return;
      __pos(e, this);
      x = __mx;
      y = __my;
      draw();
    });

    x = 50;
    y = 50;
