    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var a, b;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("roll").addEventListener('click', function () {
      a = mathRandomInt(1, 6);
      b = mathRandomInt(1, 6);
      document.getElementById("d1").textContent = a;
      document.getElementById("d2").textContent = b;
      document.getElementById("sum").textContent = '합: ' + String(a + b);
      __add("log", [a,' + ',b].join(''));
      if (a == b) {
        document.getElementById("msg").textContent = '더블!';
