  <script>
    const questions = [{"q":"'손'의 영어 단어는?","a":"hand","o":["hand","nose","arm"]},{"q":"'팔'의 영어 단어는?","a":"arm","o":["arm","foot","ear"]},{"q":"'발'의 영어 단어는?","a":"foot","o":["foot","ear","mouth"]},{"q":"'귀'의 영어 단어는?","a":"ear","o":["mouth","hand","ear"]},{"q":"'입'의 영어 단어는?","a":"mouth","o":["eye","mouth","foot"]},{"q":"'다리'의 영어 단어는?","a":"leg","o":["leg","ear","nose"]},{"q":"'코'의 영어 단어는?","a":"nose","o":["eye","nose","hand"]},{"q":"'머리'의 영어 단어는?","a":"head","o":["head","ear","mouth"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

