      if (e.key === "Enter") {
        e.preventDefault();
        if (document.getElementById("typeIn").value == document.getElementById("wordTx").textContent) {
          score = (typeof score === 'number' ? score : 0) + 1;
          document.getElementById("scoreTx").textContent = 'Score: ' + String(score);
          document.getElementById("wordTx").textContent = listsGetRandomItem(words, false);
        } else {
          document.getElementById("scoreTx").textContent = 'Typo! Try again';
        }
        document.getElementById("typeIn").value = '';
      }
    });

    words = ['cat', 'dog', 'fish'];
