<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Coin Flip</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h1 id="coin">🪙</h1>
  <button id="flip">Flip</button>
  <p id="tally">Heads: 0 / Tails: 0</p>
  <script>
    var h, t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("flip").addEventListener('click', function () {
      if (mathRandomInt(1, 2) == 1) {
        document.getElementById("coin").textContent = 'Heads';
        h = (typeof h === 'number' ? h : 0) + 1;
      } else {
        document.getElementById("coin").textContent = 'Tails';
        t = (typeof t === 'number' ? t : 0) + 1;
      }
      document.getElementById("tally").textContent = ['Heads: ',h,' / Tails: ',t].join('');
    });

    h = 0;
    t = 0;
  </script>
</body>
</html>
