  </style>
</head>
<body>
  <h1 id="title1">Word reverser</h1>
  <input id="wordBox" type="text" placeholder="Type a word">
  <button id="revBtn">Reverse</button>
  <h2 id="out"></h2>
  <h3 id="pal"></h3>
  <script>
    var w, r, i;

    document.getElementById("revBtn").addEventListener('click', function () {
      w = document.getElementById("wordBox").value;
      r = '';
      var i_end = w.length;
      var i_inc = 1;
      if (1 > i_end) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
        r = String(w.charAt((i - 1))) + String(r);
      }
      document.getElementById("out").textContent = r;
      if (r == w && !!w.length) {
        document.getElementById("pal").textContent = 'Palindrome!';
      } else {
        document.getElementById("pal").textContent = '';
      }
    });
  </script>
</body>
</html>
