    const questions = [{"q":"'배'의 영어 단어는?","a":"pear","o":["pear","banana","strawberry","apple"]},{"q":"'체리'의 영어 단어는?","a":"cherry","o":["banana","peach","cherry","tangerine"]},{"q":"'바나나'의 영어 단어는?","a":"banana","o":["grape","lemon","banana","peach"]},{"q":"'사과'의 영어 단어는?","a":"apple","o":["pear","apple","peach","watermelon"]},{"q":"'귤'의 영어 단어는?","a":"tangerine","o":["apple","cherry","tangerine","strawberry"]},{"q":"'딸기'의 영어 단어는?","a":"strawberry","o":["apple","peach","grape","strawberry"]},{"q":"'복숭아'의 영어 단어는?","a":"peach","o":["tangerine","peach","lemon","cherry"]},{"q":"'레몬'의 영어 단어는?","a":"lemon","o":["lemon","cherry","strawberry","apple"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

