    const questions = [{"q":"'배'의 영어 단어는?","a":"pear","o":["pear","apple","grape"]},{"q":"'복숭아'의 영어 단어는?","a":"peach","o":["lemon","peach","apple"]},{"q":"'딸기'의 영어 단어는?","a":"strawberry","o":["grape","strawberry","cherry"]},{"q":"'체리'의 영어 단어는?","a":"cherry","o":["watermelon","strawberry","cherry"]},{"q":"'레몬'의 영어 단어는?","a":"lemon","o":["tangerine","lemon","banana"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
