    const questions = [{"q":"'레몬'의 영어 단어는?","a":"lemon","o":["tangerine","lemon","cherry","watermelon"]},{"q":"'포도'의 영어 단어는?","a":"grape","o":["tangerine","lemon","watermelon","grape"]},{"q":"'딸기'의 영어 단어는?","a":"strawberry","o":["strawberry","watermelon","peach","lemon"]},{"q":"'귤'의 영어 단어는?","a":"tangerine","o":["grape","lemon","tangerine","apple"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

