<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>별 받기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #0f172a; color: #f1f5f9; text-align: center; }
  </style>
</head>
<body>
  <h3 id="info">점수 0 / 목숨 3</h3>
  <h1 id="star">⭐</h1>
  <h1 id="basket">🧺</h1>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __where(name, axis) {
      var r = $(name).getBoundingClientRect();
      return Math.round(axis === 'x' ? r.left + window.pageXOffset : r.top + window.pageYOffset);
    }
    function __hit(a, b) {
      var p = $(a).getBoundingClientRect(), q = $(b).getBoundingClientRect();
      return p.left < q.right && p.right > q.left && p.top < q.bottom && p.bottom > q.top;
    }
    var __cx = 0, __cy = 0;
    var __timers = [];

    var score, life;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function drop() {
      __move("star", mathRandomInt(20, 280), 70);
    }

    __timers.push(setInterval(function () {
      if (life > 0) {
        __move("basket", __cx - 20, 330);
        __nudge("star", 0, 6);
        if (__hit("star", "basket")) {
          score = (typeof score === 'number' ? score : 0) + 1;
          drop();
          document.getElementById("info").textContent = ['점수 ',score,' / 목숨 ',life].join('');
        } else {
          if (__where("star", "y") > 380) {
            life = (typeof life === 'number' ? life : 0) + -1;
            drop();
            document.getElementById("info").textContent = ['점수 ',score,' / 목숨 ',life].join('');
            if (life == 0) {
              document.getElementById("info").textContent = '게임 끝! 점수 ' + String(score);
            }
          }
        }
      }
    }, 30));

    score = 0;
    life = 3;
    drop();
  </script>
</body>
</html>
