  <h3 id="msg"></h3>
  <script>
    var m, p;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("atk").addEventListener('click', function () {
      if (m > 0 && p > 0) {
        m = (typeof m === 'number' ? m : 0) + (0 - mathRandomInt(5, 12));
        p = (typeof p === 'number' ? p : 0) + (0 - mathRandomInt(2, 8));
        document.getElementById("mhp").textContent = 'Monster HP: ' + String(Math.min(Math.max(m, 0), 50));
        document.getElementById("php").textContent = 'My HP: ' + String(Math.min(Math.max(p, 0), 30));
