  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'복숭아'의 영어 단어는?","a":"peach","o":["cherry","grape","peach"]},{"q":"'딸기'의 영어 단어는?","a":"strawberry","o":["grape","pear","strawberry"]},{"q":"'배'의 영어 단어는?","a":"pear","o":["pear","grape","tangerine"]},{"q":"'바나나'의 영어 단어는?","a":"banana","o":["apple","banana","tangerine"]},{"q":"'레몬'의 영어 단어는?","a":"lemon","o":["lemon","watermelon","tangerine"]},{"q":"'귤'의 영어 단어는?","a":"tangerine","o":["tangerine","peach","lemon"]},{"q":"'체리'의 영어 단어는?","a":"cherry","o":["peach","lemon","cherry"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
