  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'곰'의 영어 단어는?","a":"bear","o":["tiger","giraffe","bear","horse"]},{"q":"'오리'의 영어 단어는?","a":"duck","o":["dog","tiger","monkey","duck"]},{"q":"'강아지'의 영어 단어는?","a":"dog","o":["tiger","dog","elephant","duck"]},{"q":"'말'의 영어 단어는?","a":"horse","o":["horse","pig","cat","giraffe"]},{"q":"'토끼'의 영어 단어는?","a":"rabbit","o":["duck","rabbit","elephant","monkey"]},{"q":"'돼지'의 영어 단어는?","a":"pig","o":["monkey","rabbit","pig","elephant"]},{"q":"'기린'의 영어 단어는?","a":"giraffe","o":["duck","dog","bear","giraffe"]},{"q":"'사자'의 영어 단어는?","a":"lion","o":["tiger","lion","horse","pig"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
