        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("cv").addEventListener('click', function (e) {
      __pos(e, this);
      __circle("cv", __mx, __my, mathRandomInt(6, 18), 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)');
      dots = (typeof dots === 'number' ? dots : 0) + 1;
