<body>
  <h2 id="q"></h2>
  <div id="r" class="box row">
    <button id="o">⭕</button>
    <button id="x">❌</button>
  </div>
  <p id="res"></p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var a, qs, i, s;

    // 이 함수를 설명하세요...
    function answer(a) {
      if (a == 'XOX'.charAt((i - 1))) {
        s = (typeof s === 'number' ? s : 0) + 1;
        document.getElementById("res").textContent = '맞았어요! ⭕';
      } else {
        document.getElementById("res").textContent = '틀렸어요 ❌';
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > 3) {
        document.getElementById("q").textContent = ['끝! 점수: ',s,'/3'].join('');
        __show("o", "hide");
        __show("x", "hide");
      } else {
        document.getElementById("q").textContent = qs[(i - 1)];
