    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    ul { display: inline-block; text-align: left; }
  </style>
</head>
<body>
  <h1 id="title1">구구단 표</h1>
  <input id="danBox" type="number" placeholder="몇 단?">
  <button id="showBtn">보여줘</button>
  <ul id="table"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var dan, i;

    document.getElementById("showBtn").addEventListener('click', function () {
      document.getElementById("table").textContent = '';
      dan = (parseFloat(document.getElementById("danBox").value) || 0);
      for (i = 1; i <= 9; i++) {
        __add("table", [dan,' × ',i,' = ',dan * i].join(''));
