<body>
  <h1>🎲 주사위 2개 굴리기</h1>
  <div><span class="die" id="d1">⚀</span><span class="die" id="d2">⚀</span></div>
  <p id="sum">버튼을 눌러 굴려 보세요</p>
  <button id="roll">굴리기</button>
  <p>지난 기록: <span id="history">-</span></p>
  <script>
    const faces = ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];
    const rollBtn = document.getElementById('roll');
    let d1 = 1, d2 = 1;
    let rolling = false;
    let history = [];

    function randomDie() {
      return Math.floor(Math.random() * 6) + 1;
    }

    function show() {
      document.getElementById('d1').textContent = faces[d1 - 1];
      document.getElementById('d2').textContent = faces[d2 - 1];
    }

    rollBtn.addEventListener('click', function () {
      if (rolling) return;
      rolling = true;
      rollBtn.disabled = true;
      let count = 0;
      // 데굴데굴 굴러가는 것처럼 10번 바꾼 다음 멈춰요
      const timer = setInterval(function () {
        d1 = randomDie();
        d2 = randomDie();
        show();
        count += 1;
        if (count >= 10) {
          clearInterval(timer);
          rolling = false;
          rollBtn.disabled = false;
          const sum = d1 + d2;
          let text = '합계: ' + sum;
          if (d1 === d2) text += ' 🎉 더블!';
          document.getElementById('sum').textContent = text;
          history.unshift(sum);
          history = history.slice(0, 5);
          document.getElementById('history').textContent = history.join(', ');
        }
      }, 60);
    });
  </script>
</body>
</html>
