    const result = document.getElementById('result');
    document.getElementById('go').addEventListener('click', function () {
      beep();
      const x = Number(input.value);
      const y = x * 9 / 5 + 32;
      result.textContent = x + ' celsius = ' + Math.round(y * 100) / 100 + ' fahrenheit';
    });
