    <input id="emailBox" type="text" placeholder="이메일">
    <input id="ageBox" type="number" placeholder="나이">
    <input id="pwBox" type="text" placeholder="비밀번호">
    <input id="pw2Box" type="text" placeholder="비밀번호 확인">
    <button id="submit">가입하기</button>
    <p id="error"></p>
  </div>
  <h2 id="welcome"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    document.getElementById("submit").addEventListener('click', function () {
      if (!document.getElementById("nameBox").value.trim().length) {
        document.getElementById("error").textContent = '이름을 써 주세요';
      } else if (document.getElementById("emailBox").value.indexOf('@') + 1 == 0) {
        document.getElementById("error").textContent = '이메일에 @가 있어야 해요';
      } else if ((parseFloat(document.getElementById("ageBox").value) || 0) < 1 || (parseFloat(document.getElementById("ageBox").value) || 0) > 120) {
        document.getElementById("error").textContent = '나이는 1~120 사이로 써 주세요';
      } else if (document.getElementById("pwBox").value.length < 10) {
        document.getElementById("error").textContent = '비밀번호는 10자 이상이어야 해요';
      } else if (document.getElementById("pwBox").value != document.getElementById("pw2Box").value) {
        document.getElementById("error").textContent = '비밀번호가 서로 달라요';
      } else {
        __show("form", "hide");
        document.getElementById("welcome").textContent = ['가입 완료! 환영해요, ',document.getElementById("nameBox").value.trim(),'!'].join('');
      }
    });

    document.getElementById("error").style.color = "#ef4444";
  </script>
</body>
