<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>영어 과일 퀴즈</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fff8e1; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
  </style>
</head>
<body>
  <h1>영어 과일 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'사과'의 영어 단어는?","a":"apple","o":["grape","pear","apple","peach"]},{"q":"'체리'의 영어 단어는?","a":"cherry","o":["grape","cherry","peach","strawberry"]},{"q":"'레몬'의 영어 단어는?","a":"lemon","o":["lemon","peach","pear","strawberry"]},{"q":"'복숭아'의 영어 단어는?","a":"peach","o":["watermelon","tangerine","lemon","peach"]},{"q":"'바나나'의 영어 단어는?","a":"banana","o":["banana","cherry","apple","peach"]},{"q":"'포도'의 영어 단어는?","a":"grape","o":["apple","cherry","grape","pear"]},{"q":"'배'의 영어 단어는?","a":"pear","o":["tangerine","cherry","apple","pear"]},{"q":"'귤'의 영어 단어는?","a":"tangerine","o":["pear","banana","peach","tangerine"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
