  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'형'의 영어 단어는?","a":"older brother","o":["grandfather","older brother","younger sibling"]},{"q":"'할아버지'의 영어 단어는?","a":"grandfather","o":["younger sibling","grandfather","grandmother"]},{"q":"'아빠'의 영어 단어는?","a":"dad","o":["younger sibling","older sister","dad"]},{"q":"'엄마'의 영어 단어는?","a":"mom","o":["older sister","mom","older brother"]},{"q":"'누나'의 영어 단어는?","a":"older sister","o":["grandfather","older sister","older brother"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
