  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'칠판'의 영어 단어는?","a":"blackboard","o":["bag","blackboard","scissors","chair"]},{"q":"'의자'의 영어 단어는?","a":"chair","o":["chair","book","blackboard","ruler"]},{"q":"'지우개'의 영어 단어는?","a":"eraser","o":["eraser","pencil","book","ruler"]},{"q":"'가위'의 영어 단어는?","a":"scissors","o":["ruler","scissors","pencil","book"]},{"q":"'가방'의 영어 단어는?","a":"bag","o":["bag","chair","scissors","pencil"]},{"q":"'자'의 영어 단어는?","a":"ruler","o":["eraser","ruler","chair","notebook"]},{"q":"'책상'의 영어 단어는?","a":"desk","o":["book","pencil","notebook","desk"]},{"q":"'연필'의 영어 단어는?","a":"pencil","o":["scissors","pencil","blackboard","book"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
        const btn = document.createElement('button');
        btn.textContent = text;
        btn.addEventListener('click', function () {
          if (answered) return;
          answered = true;
          if (text === q.a) {
            score += 1;
            feedback.textContent = '정답!';
          } else {
            feedback.textContent = '아쉬워요. 정답은 ' + q.a;
          }
          index += 1;
          setTimeout(showQuestion, 700);
        });
        optionsEl.appendChild(btn);
      });
    }

    showQuestion();
  </script>
</body>
</html>
