<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>자동차 피하기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #e5e7eb; color: #1f2937; padding: 24px; }
    canvas { background: #374151; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🚗 자동차 피하기</h1>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span></p>
  <canvas id="game" width="300" height="450"></canvas>
  <p id="msg">← → 키로 차선을 바꿔요</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const LANE_W = W / 3;
    const msg = document.getElementById('msg');
    const startBtn = document.getElementById('start');

    let lane = 1;                         // 0, 1, 2 차선
    let player = { x: 0, y: 380, w: 50, h: 60 };
    let cars = [];
    let score = 0;
    let lives = 3;
    let safeTime = 0;
    let spawnWait = 0;
    let roadY = 0;
    let running = false;
    let timer = null;

    function laneX(n) {
      return n * LANE_W + (LANE_W - 50) / 2;
    }

    function overlap(a, b) {
      return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
    }

    function startGame() {
      clearInterval(timer);
      lane = 1;
      player.x = laneX(lane);
      cars = [];
      score = 0;
      lives = 3;
      safeTime = 0;
      spawnWait = 0;
      running = true;
      msg.textContent = '';
      startBtn.textContent = '다시 시작';
      updateInfo();
      timer = setInterval(tick, 20);
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! 점수: ' + score;
    }

    function tick() {
      if (!running) return;
      const speed = 5 + score * 0.15;
      roadY = (roadY + speed) % 40;
      spawnWait -= 1;
      if (spawnWait <= 0) {
        cars.push({ x: laneX(Math.floor(Math.random() * 3)), y: -60, w: 50, h: 60 });
        spawnWait = Math.max(18, 45 - score);
      }
      for (let i = cars.length - 1; i >= 0; i--) {
        cars[i].y += speed;
        if (cars[i].y > H) {
          cars.splice(i, 1);
          score += 1;
          updateInfo();
        }
      }
      if (safeTime > 0) {
        safeTime -= 1;
      } else {
        for (let i = 0; i < cars.length; i++) {
          if (overlap(player, cars[i])) {
            cars.splice(i, 1);
            lives = Math.max(0, lives - 1);
            safeTime = 50;
            updateInfo();
            if (lives === 0) gameOver();
            break;
          }
        }
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#e5e7eb';
      for (let l = 1; l < 3; l++) {
        for (let y = roadY - 40; y < H; y += 40) ctx.fillRect(l * LANE_W - 2, y, 4, 20);
      }
      ctx.fillStyle = '#f97316';
      cars.forEach(function (c) { ctx.fillRect(c.x, c.y, c.w, c.h); });
      if (safeTime % 10 < 5) {
        ctx.fillStyle = '#22d3ee';
        ctx.fillRect(player.x, player.y, player.w, player.h);
      }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      if (!running) return;
      // 한 번 누르면 한 차선씩: x만 바뀌어요
      if (e.key === 'ArrowLeft' && lane > 0) lane -= 1;
      if (e.key === 'ArrowRight' && lane < 2) lane += 1;
      player.x = laneX(lane);
    });
    startBtn.addEventListener('click', startGame);
    player.x = laneX(lane);
    draw();
  </script>
</body>
</html>
