  </style>
</head>
<body>
  <h1 id="t">🐝 Spelling bee</h1>
  <button id="say">Show a word</button>
  <h2 id="word"></h2>
  <div id="r" class="box row">
    <input id="ans" type="text" placeholder="Type the spelling">
    <button id="chk">Check</button>
  </div>
  <h2 id="res"></h2>
  <p id="cnt">Correct: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var words, w, ok;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("say").addEventListener('click', function () {
      w = listsGetRandomItem(words, false);
      document.getElementById("word").textContent = w;
      __show("word", "show");
      document.getElementById("res").textContent = '';
      setTimeout(function () {
        __show("word", "hide");
      }, (2) * 1000);
    });
    document.getElementById("chk").addEventListener('click', function () {
      if (document.getElementById("ans").value.trim() == w) {
        ok = (typeof ok === 'number' ? ok : 0) + 1;
        document.getElementById("res").textContent = 'Correct! ✅';
        document.getElementById("cnt").textContent = 'Correct: ' + String(ok);
      } else {
        document.getElementById("res").textContent = 'Incorrect - it was ' + String(w);
      }
      document.getElementById("ans").value = '';
    });

    words = ['because', 'friend', 'school', 'beautiful', 'library'];
    w = listsGetRandomItem(words, false);
    ok = 0;
  </script>
</body>
</html>
