<body>
  <h1 id="title">🎬 Guess the movie</h1>
  <h1 id="clue"></h1>
  <h2 id="answer"></h2>
  <div id="r" class="box row">
    <button id="reveal">Reveal</button>
    <button id="next">Next</button>
  </div>
  <script>
    var k, clues, titles;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function pick() {
      k = mathRandomInt(1, 5);
      document.getElementById("clue").textContent = clues[(k - 1)];
      document.getElementById("answer").textContent = '';
    }

    document.getElementById("reveal").addEventListener('click', function () {
      document.getElementById("answer").textContent = titles[(k - 1)];
    });
    document.getElementById("next").addEventListener('click', function () {
      pick();
    });

    clues = ['🦁👑', '❄️👸⛄', '🕷️🧑', '🧸🤠🚀', '🐠🔍'];
    titles = ['The Lion King', 'Frozen', 'Spider-Man', 'Toy Story', 'Finding Nemo'];
    pick();
  </script>
</body>
</html>
