<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>구구단 퀴즈</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #ecfdf5; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 24px; padding: 8px; margin: 4px; width: 100px; text-align: center; }
    #problem { font-size: 48px; font-weight: bold; margin: 12px; }
    #feedback { font-size: 22px; min-height: 28px; }
  </style>
</head>
<body>
  <h1>✖️ 구구단 퀴즈 10문제</h1>
  <p>문제 <span id="num">1</span>/10 · 맞힌 개수: <span id="score">0</span></p>
  <div id="problem"></div>
  <input id="answer" type="number">
  <button id="check">확인</button>
  <p id="feedback"></p>
  <button id="restart">다시 하기</button>
  <script>
    const TOTAL = 10;
    let a = 2, b = 2;
    let num = 1;
    let score = 0;
    let finished = false;
    const input = document.getElementById('answer');
    const feedback = document.getElementById('feedback');

    function newProblem() {
      a = Math.floor(Math.random() * 8) + 2; // 2~9단
      b = Math.floor(Math.random() * 9) + 1;
      document.getElementById('problem').textContent = a + ' × ' + b + ' = ?';
      document.getElementById('num').textContent = num;
      input.value = '';
      input.focus();
    }

    function check() {
      if (finished || input.value === '') return;
      if (Number(input.value) === a * b) {
        score += 1;
        feedback.textContent = '⭕ 정답!';
      } else {
        feedback.textContent = '❌ 아쉬워요. ' + a + ' × ' + b + ' = ' + (a * b);
      }
      document.getElementById('score').textContent = score;
      if (num >= TOTAL) {
        finished = true;
        document.getElementById('problem').textContent = '끝! 10문제 중 ' + score + '개 정답';
        input.value = '';
        input.disabled = true;
        return;
      }
      num += 1;
      newProblem();
    }

    function restart() {
      num = 1;
      score = 0;
      finished = false;
      input.disabled = false;
      feedback.textContent = '';
      document.getElementById('score').textContent = 0;
      newProblem();
    }

    document.getElementById('check').addEventListener('click', check);
    input.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') check();
    });
    document.getElementById('restart').addEventListener('click', restart);
    restart();
  </script>
</body>
</html>
