```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Whack a mole</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #dcfce7; color: #1f2937; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h2 id="info">Score: 0 · 15s</h2>
  <button id="mole">🐹</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var s, t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("mole").addEventListener('click', function () {
      if (t > 0) {
        s = (typeof s === 'number' ? s : 0) + 1;
        document.getElementById("info").textContent = ['Score: ',s,' · ',t,'s'].join('');
      }
    });
    __timers.push(setInterval(function () {
      t = (typeof t === 'number' ? t : 0) + -1;
      __move("mole", mathRandomInt(20, 300), mathRandomInt(60, 360));
      document.getElementById("info").textContent = ['Score: ',s,' · ',t,'s'].join('');
      if (t == 0) {
        __timers.forEach(clearInterval);
        __show("mole", "hide");
        document.getElementById("info").textContent = 'Time up! Your score: ' + String(s);
      }
    }, 1000));

    s = 0;
    t = 15;
  </script>
</body>
</html>
