    <button id="toggleB">시작/멈춤</button>
    <button id="reset">리셋</button>
  </div>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }
    var __timers = [];

    var t, run;

    document.getElementById("toggleB").addEventListener('click', function () {
      run = !run;
    });
    document.getElementById("reset").addEventListener('click', function () {
      run = false;
      t = 0;
      document.getElementById("show").textContent = 0;
    });
    __timers.push(setInterval(function () {
      if (run) {
        t = (typeof t === 'number' ? t : 0) + 1;
        document.getElementById("show").textContent = t / 10;
      }
    }, 100));

    t = 0;
    run = false;
    __size("show", "fontSize", 64);
  </script>
</body>
</html>
