  <h2 id="title1">점 잇기</h2>
  <canvas id="cv" width="320" height="320"></canvas>
  <button id="resetBtn">처음부터</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }
    function __line(name, x1, y1, x2, y2, color) { var g = __pen(name); g.strokeStyle = color; g.lineWidth = 3; g.lineCap = 'round'; g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.stroke(); }

    var first, x, y, px, py;

    document.getElementById("cv").addEventListener('click', function (e) {
      __pos(e, this);
      x = __mx;
      y = __my;
      if (!first) {
        __line("cv", px, py, x, y, "#111111");
      }
      __circle("cv", x, y, 4, "#111111");
      px = x;
      py = y;
      first = false;
    });
    document.getElementById("resetBtn").addEventListener('click', function () {
      __clear("cv");
      first = true;
    });

    first = true;
  </script>
</body>
</html>
