</head>
<body>
  <h1>영어 몸 퀴즈</h1>
  <p id="info"></p>
  <h2 id="question"></h2>
  <div id="options"></div>
  <p id="feedback"></p>
  <script>
    const questions = [{"q":"'손'의 영어 단어는?","a":"hand","o":["leg","hand","ear","mouth"]},{"q":"'머리'의 영어 단어는?","a":"head","o":["nose","foot","mouth","head"]},{"q":"'팔'의 영어 단어는?","a":"arm","o":["head","leg","arm","ear"]},{"q":"'눈'의 영어 단어는?","a":"eye","o":["ear","eye","arm","nose"]},{"q":"'귀'의 영어 단어는?","a":"ear","o":["mouth","arm","ear","foot"]},{"q":"'다리'의 영어 단어는?","a":"leg","o":["eye","leg","mouth","hand"]},{"q":"'입'의 영어 단어는?","a":"mouth","o":["ear","mouth","nose","arm"]},{"q":"'발'의 영어 단어는?","a":"foot","o":["arm","mouth","foot","leg"]},{"q":"'코'의 영어 단어는?","a":"nose","o":["arm","head","foot","nose"]}];
    let index = 0;
    let score = 0;
    let answered = false;
    const info = document.getElementById('info');
    const questionEl = document.getElementById('question');
    const optionsEl = document.getElementById('options');
    const feedback = document.getElementById('feedback');

    function showQuestion() {
      if (index >= questions.length) {
        questionEl.textContent = '끝! 점수: ' + score + ' / ' + questions.length;
        optionsEl.innerHTML = '';
        feedback.textContent = '';
        info.textContent = '';
        return;
      }
      const q = questions[index];
      answered = false;
      info.textContent = (index + 1) + ' / ' + questions.length + ' · 점수 ' + score;
      questionEl.textContent = q.q;
      feedback.textContent = '';
      optionsEl.innerHTML = '';
      q.o.forEach(function (text) {
